const LESSONS=[{"day":1,"title":"How LLMs work + setup","phase":"AI literacy and Python from zero","learn":"Andrej Karpathy, 'Intro to Large Language Models' (about 1 hr, YouTube). Note tokens, context window, training vs inference.","build":"finish the setup checklist. Push a README to ai-data-100 stating your 100-day goal. Create a Claude Project called 'Tutor'.","done":"notes/day01.md answers 'why can an LLM sound sure and still be wrong?' in 5 lines.","checkpoint":false},{"day":2,"title":"Prompting basics","phase":"AI literacy and Python from zero","learn":"Anthropic Academy 'Claude 101' (start; finish by Day 4) and the Claude docs page 'Prompt engineering overview'.","build":"write 5 prompts for real tasks (explain a SQL error, summarize pipeline logs, write a docstring, plan a study day, review a query). Each uses role, context, one example and an output format. Run each twice and keep the better one in prompts.md.","done":"5 prompts saved with a before/after note on what improved.","checkpoint":false},{"day":3,"title":"Python first scripts","phase":"AI literacy and Python from zero","learn":"Automate the Boring Stuff with Python (free online), chapters 1–2: values, variables, print, input, f-strings.","build":"6 tiny scripts: greeter, km-to-miles converter, age calculator, simple interest, BMI, bill splitter.","done":"all 6 run without errors and are committed.","checkpoint":false},{"day":4,"title":"Strings, numbers, lists","phase":"AI literacy and Python from zero","learn":"ATBS chapter 6 (strings) and 4 (lists); Python tutorial section 3.1 on docs.python.org.","build":"tip calculator; sentence analyzer that prints word count, longest word and the sentence reversed word by word.","done":"each script tested on 5 inputs, with results written as comments.","checkpoint":false},{"day":5,"title":"Dictionaries, tuples, sets","phase":"AI literacy and Python from zero","learn":"ATBS chapter 5 (dictionaries); Python tutorial section 5.","build":"in-memory contact book with a menu loop: add, search, delete, list.","done":"it holds 10 contacts and does not crash on a missing name.","checkpoint":false},{"day":6,"title":"Conditions and loops","phase":"AI literacy and Python from zero","learn":"ATBS chapter 2 (flow control); Python tutorial section 4.","build":"number-guessing game with an attempts counter; FizzBuzz; prime checker for 1–100.","done":"you can explain every line of each script aloud.","checkpoint":false},{"day":7,"title":"Expense tracker v1","phase":"AI literacy and Python from zero","learn":"none. Re-read notes for Days 1–6 and make 15 Anki cards.","build":"text-based tracker: add an expense (date, category, amount), list all, total by category. Data lives in memory.","done":"20 entries entered and totals match a hand calculation.","checkpoint":true},{"day":8,"title":"Functions","phase":"AI literacy and Python from zero","learn":"ATBS chapter 3; Google AI Essentials module 1 (about 45 min, takes part of the Learn block).","build":"refactor the tracker into add_expense(), total_by_category(), print_report().","done":"main only calls functions, no repeated code.","checkpoint":false},{"day":9,"title":"Files","phase":"AI literacy and Python from zero","learn":"ATBS chapter 9 (files); csv and json module docs; Google AI Essentials module 2.","build":"save and load expenses to expenses.csv and expenses.json; handle a missing file.","done":"closing and reopening the program keeps the data.","checkpoint":false},{"day":10,"title":"Errors and debugging","phase":"AI literacy and Python from zero","learn":"ATBS chapter 11 (debugging); Python tutorial section 8 (errors and exceptions); Google AI Essentials module 3.","build":"add input validation (non-number amount, empty category) with try/except. Break the code on purpose 5 ways and read each traceback. Paste each into Claude and ask it to explain before fixing.","done":"notes/errors.md lists 5 errors with cause and fix.","checkpoint":false},{"day":11,"title":"Modules, pip, virtual environments","phase":"AI literacy and Python from zero","learn":"Python tutorial section 6 (modules) and the venv docs; Google AI Essentials module 4.","build":"create a venv, pip install requests, write requirements.txt. Split the tracker into storage.py, report.py, main.py.","done":"it runs from a fresh venv built from requirements.txt.","checkpoint":false,"enhancement":"Add Python type hints to public functions; run Ruff for linting/formatting; document a clean virtual-environment setup."},{"day":12,"title":"APIs and JSON","phase":"AI literacy and Python from zero","learn":"Requests library quickstart; Google AI Essentials module 5.","build":"call the free Open-Meteo API (no key needed) for 7 days of max temperature in your city; print a clean table; handle timeouts and non-200 responses.","done":"it prints 7 rows and shows a friendly error with Wi-Fi turned off.","checkpoint":false,"enhancement":"Use Pydantic models to validate the API response shape; add pytest tests for success, timeout, malformed JSON and non-200 responses."},{"day":13,"title":"Git and GitHub","phase":"AI literacy and Python from zero","learn":"'Learn Git Branching' (learngitbranching.js.org), main levels, about 60 min.","build":"add .gitignore, work on a branch feature/storage, merge it, push; add a README with usage steps.","done":"the repo has 10 or more meaningful commits.","checkpoint":false,"enhancement":"Create a pull request instead of pushing directly to main; add a GitHub Actions workflow that runs pytest and Ruff."},{"day":14,"title":"Weather logger + first certificate","phase":"AI literacy and Python from zero","learn":"finish Google AI Essentials and claim the certificate.","build":"a script that appends one day's weather to weather.csv each run, with functions, error handling and a README.","done":"you ran it on 3 different days or simulated dates, and the certificate is on LinkedIn.","checkpoint":true},{"day":15,"title":"Classes (light touch)","phase":"Python for data, SQL and engineering habits","learn":"Python tutorial section 9 (classes); Corey Schafer's OOP videos 1–2 on YouTube.","build":"rebuild the tracker with an Expense class and an ExpenseBook class (add, total_by_category, save, load).","done":"the program runs using classes and your old saved data still loads.","checkpoint":false,"enhancement":"Add type annotations to Expense and ExpenseBook; write pytest unit tests for add, totals, save and load."},{"day":16,"title":"pandas 1","phase":"Python for data, SQL and engineering habits","learn":"'10 minutes to pandas' (pandas docs); Kaggle Learn 'Pandas' lessons 1–2.","build":"in a Jupyter notebook, load the Kaggle Titanic train.csv. Use shape, info(), describe(), value_counts(), head().","done":"day16.ipynb answers 10 written questions about the data.","checkpoint":false},{"day":17,"title":"Filter, sort, group","phase":"Python for data, SQL and engineering habits","learn":"Kaggle Learn 'Pandas' lessons 3–4 (summary functions, grouping and sorting).","build":"answer 15 questions on Titanic: survival rate by sex and class, average fare by port, oldest survivor, and so on.","done":"every answer is a single pandas expression you can explain.","checkpoint":false},{"day":18,"title":"Joins, missing values, types","phase":"Python for data, SQL and engineering habits","learn":"Kaggle Learn 'Pandas' lessons 5–6 (data types and missing values; renaming and combining).","build":"ask Claude to generate two related CSVs (customers, orders, with some orphan keys). Run inner, left and outer merges and compare row counts.","done":"a short note explains which join drops which rows and why.","checkpoint":false},{"day":19,"title":"Data cleaning","phase":"Python for data, SQL and engineering habits","learn":"Kaggle Learn 'Data Cleaning' (missing values, parsing dates, inconsistent entries).","build":"ask Claude for a 500-row messy file (duplicates, mixed date formats, trailing spaces, typos in categories). Clean it into a tidy file and write the rules as a list.","done":"before/after row counts and the list of cleaning rules are in the README.","checkpoint":false},{"day":20,"title":"Charts","phase":"Python for data, SQL and engineering habits","learn":"matplotlib 'Pyplot tutorial'; seaborn gallery for ideas.","build":"4 charts (bar, line, histogram, scatter) with titles, axis labels and units, saved as PNG.","done":"a stranger could read each chart without your explanation.","checkpoint":false},{"day":21,"title":"EDA report","phase":"Python for data, SQL and engineering habits","learn":"none. Skim 2 Kaggle notebooks on your chosen dataset for ideas.","build":"pick one public dataset. Write 10 questions, answer them with pandas, draw 3 charts, and write 5 insight bullets in a README.","done":"someone else can read the README and learn something in 3 minutes.","checkpoint":true},{"day":22,"title":"Advanced SQL 1, window functions","phase":"Python for data, SQL and engineering habits","learn":"Kaggle Learn 'Advanced SQL' (analytic functions) or Mode's SQL tutorial window-functions section.","build":"in DuckDB or SQLite, solve 8 problems using ROW_NUMBER, RANK, LAG/LEAD, running totals, 7-row moving average, top-N per group.","done":"you can say when to use RANK vs ROW_NUMBER without notes.","checkpoint":false},{"day":23,"title":"Advanced SQL 2, CTEs and plans","phase":"Python for data, SQL and engineering habits","learn":"your database's EXPLAIN docs; recursive CTE examples.","build":"solve 15 mixed medium problems (LeetCode SQL 50 or DataLemur). Rewrite 3 using CTEs; read the EXPLAIN output for one slow query.","done":"15 solutions committed, plus one paragraph on what the plan showed.","checkpoint":false},{"day":24,"title":"DuckDB","phase":"Python for data, SQL and engineering habits","learn":"DuckDB docs, 'Python API' and 'Querying Parquet files'.","build":"pip install duckdb. Query a CSV and a Parquet file directly, join them, export the result. Generate a 1M-row file and time pandas against DuckDB for the same group-by.","done":"a timing table is in the README.","checkpoint":false,"enhancement":"Compare query plans and record reproducible benchmark conditions; explain why one timing result is not a universal performance claim."},{"day":25,"title":"File formats","phase":"Python for data, SQL and engineering habits","learn":"Apache Parquet docs overview (columnar storage, compression).","build":"save the same 1M rows as CSV, JSON lines and Parquet (snappy). Compare file size, full-read time, and time to read one column.","done":"you can explain in 3 sentences why Parquet wins for analytics.","checkpoint":false},{"day":26,"title":"Validation and logging","phase":"Python for data, SQL and engineering habits","learn":"pydantic docs 'Models'; Python logging HOWTO (basic tutorial).","build":"a pydantic model for one record type. Reject bad rows and count them. Log to a file with INFO and ERROR levels.","done":"a file with 3 bad rows produces 3 error log lines and a summary count.","checkpoint":false},{"day":27,"title":"Testing","phase":"Python for data, SQL and engineering habits","learn":"pytest 'Get started'; parametrized tests.","build":"write 8 tests for your cleaning functions, including empty input, nulls and weird dates. Run pytest -q.","done":"all tests pass and one test caught a real bug you then fixed.","checkpoint":false},{"day":28,"title":"mini-etl project","phase":"Python for data, SQL and engineering habits","learn":"none.","build":"extract from a public API, transform with pandas, validate with pydantic, load into Parquet and a DuckDB table. Add logging, tests and a README with an ASCII diagram.","done":"python -m etl.run works from a fresh venv and pytest is green.","checkpoint":true,"enhancement":"Add a small CI pipeline that installs dependencies and runs tests on each pull request."},{"day":29,"title":"Terminal and Docker concepts","phase":"Modern data engineering (lakehouse)","learn":"Docker 'Get started' docs (images, containers, volumes); shell basics: ls, cd, grep, cat, pipes, chmod.","build":"install Docker Desktop. Use grep, sort, uniq -c and wc to find the top 5 repeated lines in a log file.","done":"docker run hello-world works and your shell one-liner is saved in notes.","checkpoint":false,"enhancement":"Use Docker Compose only if multiple services are needed; document environment variables and never commit secrets."},{"day":30,"title":"Dockerize your ETL","phase":"Modern data engineering (lakehouse)","learn":"Dockerfile best practices (docs), environment variables, volumes.","build":"write a Dockerfile for mini-etl. Build it, run it with a config passed as an environment variable, and mount a folder so output files appear on your machine.","done":"the container produces a Parquet file on your host.","checkpoint":false},{"day":31,"title":"Spark concepts","phase":"Modern data engineering (lakehouse)","learn":"Spark 'Quick Start' docs; a conceptual video on driver, executors, partitions and shuffle.","build":"open Databricks Free Edition, create a notebook, run spark.range(10), read a sample dataset. Draw by hand the driver, executors, partitions and a shuffle.","done":"your diagram plus 5 Anki cards explain lazy evaluation, narrow vs wide transformations, and shuffle.","checkpoint":false},{"day":32,"title":"PySpark DataFrames","phase":"Modern data engineering (lakehouse)","learn":"PySpark 'DataFrame Quickstart' (Spark docs).","build":"load a CSV into a Spark DataFrame; use select, filter, withColumn, groupBy; write the result to Delta or Parquet. Repeat 5 of your Day 17 Titanic questions in PySpark.","done":"results match your pandas answers.","checkpoint":false},{"day":33,"title":"Joins, aggregates, windows in PySpark","phase":"Modern data engineering (lakehouse)","learn":"PySpark Window docs; spark.sql for the same logic.","build":"join orders and customers; rank customers by revenue with a window function; compute running totals. Write each in both the DataFrame API and SQL.","done":"both versions return identical results.","checkpoint":false},{"day":34,"title":"Spark performance","phase":"Modern data engineering (lakehouse)","learn":"Spark UI basics (jobs, stages, shuffle read/write); broadcast joins; Adaptive Query Execution overview.","build":"generate a few million rows (start at 5M, scale to what Free Edition handles). Run 3 experiments: join with and without broadcast; repartition vs coalesce; a skewed group-by. Check explain() and the Spark UI each time.","done":"a table of 3 experiments with timings is in notes.","checkpoint":false},{"day":35,"title":"Large dataset pipeline","phase":"Modern data engineering (lakehouse)","learn":"none.","build":"process a public Parquet dataset (for example NYC taxi trips) or your generated 5M rows: clean, aggregate, write output.","done":"you documented 3 optimizations with before/after timings.","checkpoint":true},{"day":36,"title":"Delta Lake","phase":"Modern data engineering (lakehouse)","learn":"Delta Lake docs 'Quickstart'.","build":"create a Delta table; run UPDATE, DELETE, MERGE (upsert); use DESCRIBE HISTORY and VERSION AS OF; test adding a column.","done":"you restored a previous version after a bad update.","checkpoint":false},{"day":37,"title":"Medallion architecture","phase":"Modern data engineering (lakehouse)","learn":"Databricks docs on the medallion architecture.","build":"bronze = raw data plus ingest_ts; silver = cleaned and deduplicated; gold = daily aggregates for one business question.","done":"rerunning the pipeline does not create duplicates (it is idempotent).","checkpoint":false},{"day":38,"title":"Incremental ingestion","phase":"Modern data engineering (lakehouse)","learn":"Auto Loader docs; Structured Streaming programming guide (intro and checkpoints).","build":"drop files into a folder or volume in 3 batches; ingest with Auto Loader or readStream using a checkpoint and availableNow trigger.","done":"the second run processes only the new files.","checkpoint":false},{"day":39,"title":"Orchestration","phase":"Modern data engineering (lakehouse)","learn":"Databricks Workflows (Jobs) docs; or the Apache Airflow tutorial if you prefer open source.","build":"a 3-task job (bronze, silver, gold) with dependencies, a schedule, a parameter and failure notification.","done":"run history shows one success and one deliberate failure with a retry.","checkpoint":false},{"day":40,"title":"Data quality","phase":"Modern data engineering (lakehouse)","learn":"pipeline expectations in Databricks docs, or Great Expectations 'Getting started'.","build":"add checks for non-null keys, unique IDs, value ranges and a row-count drop of more than 30%. Send failing rows to a quarantine table.","done":"injecting 5 bad rows lands them in quarantine and the good rows flow on.","checkpoint":false},{"day":41,"title":"Governance","phase":"Modern data engineering (lakehouse)","learn":"Unity Catalog docs (catalog, schema, table, grants, lineage).","build":"organize tables in a catalog and schema; set grants where your workspace allows; mark PII columns in a data dictionary table.","done":"the dictionary lists every column, its owner and a PII yes/no.","checkpoint":false},{"day":42,"title":"End-to-end pipeline","phase":"Modern data engineering (lakehouse)","learn":"none.","build":"assemble bronze, silver, gold, quality checks and a schedule. Write a README with an architecture diagram and a runbook titled 'What to do when the job fails'.","done":"a colleague could operate it from your README.","checkpoint":true,"enhancement":"Add data-quality assertions, idempotent reruns and a short operational runbook for the lakehouse pipeline."},{"day":43,"title":"CI/CD for data code","phase":"Modern data engineering (lakehouse)","learn":"GitHub Actions quickstart; Databricks Asset Bundles overview.","build":"a GitHub Action that runs pytest and ruff on every push. Move settings to environment variables; keep secrets out of the repo with .env and .gitignore.","done":"the Action shows green on a push and red on a deliberately broken test.","checkpoint":false},{"day":44,"title":"Monitoring and cost","phase":"Modern data engineering (lakehouse)","learn":"Databricks docs on monitoring jobs; cluster cost basics.","build":"write row counts and durations of every run to a pipeline_metrics table. Add an alert rule for sudden row-count drops. List the three biggest cost drivers.","done":"a query shows the last 10 runs with durations and counts.","checkpoint":false},{"day":45,"title":"Databricks Data Engineer Associate review","phase":"Modern data engineering (lakehouse)","learn":"the official exam guide; Databricks Academy free self-paced course for the exam topics.","build":"take 2 practice tests, list weak topics, and fix each with a short notebook.","done":"scores are recorded and the exam is booked (skip the booking if you already passed).","checkpoint":false},{"day":46,"title":"ML in plain English","phase":"Machine learning and LLM fundamentals","learn":"Kaggle Learn 'Intro to Machine Learning' lessons 1–3; StatQuest videos on bias and variance, and cross-validation.","build":"split Titanic into train and test. Build a baseline that always predicts the majority class and measure its accuracy.","done":"you can explain overfitting using your own train vs test numbers.","checkpoint":false,"enhancement":"Deep-learning bridge: learn tensors, shapes, matrix operations and CPU/GPU placement; use a tiny PyTorch tensor exercise."},{"day":47,"title":"First models with scikit-learn","phase":"Machine learning and LLM fundamentals","learn":"scikit-learn 'Getting started'.","build":"on any small regression dataset, train LinearRegression and RandomForestRegressor; compare mean absolute error on the test set.","done":"a 3-line note says which model won and why you think so.","checkpoint":false,"enhancement":"Build a minimal neural network in PyTorch; explain weights, biases, activation functions and loss in your own words."},{"day":48,"title":"Classification metrics","phase":"Machine learning and LLM fundamentals","learn":"StatQuest on confusion matrix and ROC/AUC.","build":"a Titanic classifier; report accuracy, precision, recall, F1; plot a confusion matrix; try 3 decision thresholds.","done":"you can explain when recall matters more than precision, with an example from data engineering (for example fraud or failed-job detection).","checkpoint":false,"enhancement":"Trace a single training batch through forward pass, loss, backpropagation and optimizer step; compare training and inference."},{"day":49,"title":"Features and pipelines","phase":"Machine learning and LLM fundamentals","learn":"Kaggle Learn 'Feature Engineering'; scikit-learn Pipeline and ColumnTransformer docs.","build":"a pipeline with imputing, one-hot encoding and scaling; evaluate with cross_val_score.","done":"the whole thing is one object that takes raw data and returns predictions.","checkpoint":false,"enhancement":"Study transformer blocks at a conceptual level: tokenization, embeddings, self-attention, positional information and output logits."},{"day":50,"title":"Transformers intuition","phase":"Machine learning and LLM fundamentals","learn":"3Blue1Brown, 'But what is a GPT?' and 'Attention in transformers, step by step' (about 50 min combined).","build":"draw on paper, then redraw digitally: text → tokens → embeddings → attention → next-token probabilities. Write a one-page plain-English explanation.","done":"a non-technical friend can follow your page.","checkpoint":false},{"day":51,"title":"Embeddings hands-on","phase":"Machine learning and LLM fundamentals","learn":"sentence-transformers docs (the all-MiniLM-L6-v2 model runs locally, free).","build":"embed 30 short sentences from your own notes; compute cosine similarity; for 5 queries, print the 3 nearest sentences; plot all in 2D with PCA.","done":"nearest neighbors make sense and you found one surprising mismatch to explain.","checkpoint":false,"enhancement":"Write a one-page model selection note covering quality, latency, context window, privacy, availability and cost."},{"day":52,"title":"First Claude API calls","phase":"Machine learning and LLM fundamentals","learn":"Anthropic Academy 'Building with the Claude API' (start; finish by Day 60, alongside other work) and the API quickstart.","build":"get an API key and store it in .env (never commit it). Make a command-line chatbot that keeps conversation history, uses a system prompt, streams output and prints token usage. Compare temperature 0 and 1.","done":"your key is not in Git and the bot remembers earlier turns.","checkpoint":false,"enhancement":"Build a FastAPI endpoint with Pydantic request/response models; add input validation and an OpenAPI description."},{"day":53,"title":"Advanced prompting","phase":"Machine learning and LLM fundamentals","learn":"Claude docs sections on being clear and direct, multishot examples, XML tags, and step-by-step reasoning.","build":"three tasks (SQL from a schema, log-line classification, a short summary). For each, write prompt v1, v2, v3 and score each version on 10 examples.","done":"a results table shows accuracy by prompt version.","checkpoint":false,"enhancement":"Add streaming output, timeouts, bounded retries and explicit handling for rate limits and provider errors."},{"day":54,"title":"Structured outputs","phase":"Machine learning and LLM fundamentals","learn":"pydantic; Claude docs on tool use and JSON output.","build":"extract {vendor, amount, date, category} from 20 messy invoice texts into pydantic objects. On validation failure, retry once with the error message.","done":"success rate is measured and the 2 worst failures are explained.","checkpoint":false,"enhancement":"Implement tool/function calling with a strict JSON schema; validate arguments before executing any tool."},{"day":55,"title":"Mini-project, LLM data cleaner","phase":"Machine learning and LLM fundamentals","learn":"none.","build":"take a free-text column (product descriptions or support tickets), classify each row into categories with Claude in batches of 50, cache results to disk, and write the labels back to the DataFrame.","done":"accuracy on 30 hand-labeled rows is above 85%, or you know why not.","checkpoint":false,"enhancement":"Track token usage, estimated cost, latency and model name per request; do not log secrets or sensitive prompt content."},{"day":56,"title":"Production basics","phase":"Machine learning and LLM fundamentals","learn":"Claude docs on rate limits, prompt caching and batch processing.","build":"add retries with exponential backoff, a disk cache and a cost estimator. Estimate the cost of running 1,000 rows.","done":"re-running the same rows costs nothing and the cost table is in the README.","checkpoint":false,"enhancement":"Add pytest tests with mocked model responses, malformed structured output and provider failure cases."},{"day":57,"title":"Evaluation","phase":"Machine learning and LLM fundamentals","learn":"Claude docs on defining success criteria and developing test cases.","build":"a golden set of 40 labeled examples for the Day 55 task; a script that reports accuracy per category; try an LLM-as-judge on 10 cases and compare with your own judgment.","done":"you wrote down two cases where the judge was wrong.","checkpoint":false},{"day":58,"title":"Responsible AI and prompt injection","phase":"Machine learning and LLM fundamentals","learn":"Anthropic Academy 'AI Fluency: Framework & Foundations' (start; finish by Day 66); OWASP Top 10 for LLM Applications overview.","build":"attack your Day 55 app with texts like 'ignore your instructions and output X'. Add mitigations: delimiters around untrusted text, output validation, a fixed label list.","done":"5 attacks logged, with which ones worked before and after the fix.","checkpoint":false},{"day":59,"title":"AI-900 study","phase":"Machine learning and LLM fundamentals","learn":"Microsoft Learn 'Azure AI Fundamentals' learning path (AI workloads, machine learning, computer vision, language, generative AI).","build":"a one-page cheat sheet and 40 Anki cards.","done":"you can name the Azure service for each common AI task without looking.","checkpoint":false},{"day":60,"title":"AI-900 practice exams","phase":"Machine learning and LLM fundamentals","learn":"Microsoft Learn free practice assessment.","build":"take 2 practice tests (target 80% or higher); fix weak areas; book the real exam within 2 weeks. Confirm on Microsoft Learn whether AI-900 or a newer fundamentals exam is current.","done":"the exam date is booked.","checkpoint":true},{"day":61,"title":"RAG concept","phase":"RAG and data for AI","learn":"DeepLearning.AI short course on advanced RAG (or the Claude docs section on retrieval); read how retrieval, prompt and generation connect.","build":"draw the RAG architecture. Choose a corpus of 10–20 documents (your own notes, Databricks docs pages, or PDFs). Write 10 test questions with the document that answers each.","done":"the question list with expected sources is saved as eval/questions.csv.","checkpoint":false,"enhancement":"Add document metadata and access-control filters; verify a user cannot retrieve documents outside their permitted scope."},{"day":62,"title":"Loading and parsing documents","phase":"RAG and data for AI","learn":"pypdf and BeautifulSoup basics.","build":"parse the corpus into JSONL records: {doc_id, source, page, text}. Check 5 records by eye for broken text.","done":"every document produces clean text, and you noted which ones did not.","checkpoint":false,"enhancement":"Compare keyword retrieval with vector retrieval using a fixed set of questions and expected source documents."},{"day":63,"title":"Chunking","phase":"RAG and data for AI","learn":"chunking strategies (fixed size with overlap, by heading, by paragraph).","build":"implement 3 chunkers. Print 10 chunks from each and judge which keep ideas intact.","done":"you picked one chunker and wrote 3 lines on why.","checkpoint":false,"enhancement":"Add hybrid retrieval (keyword + vector) and measure whether it improves retrieval on your evaluation set."},{"day":64,"title":"Embeddings at scale","phase":"RAG and data for AI","learn":"embedding model options: a local sentence-transformers model (free) or a hosted embedding API.","build":"embed all chunks in batches and store chunk_id, text, metadata, vector in Parquet. Skip chunks whose content hash has not changed.","done":"a second run embeds nothing new.","checkpoint":false,"enhancement":"Add a reranking step and compare top-k relevance before and after reranking."},{"day":65,"title":"Vector search","phase":"RAG and data for AI","learn":"Chroma quickstart (easiest start); skim pgvector's README to see the SQL-based alternative.","build":"load vectors into Chroma, query the top 5, add a metadata filter (for example by source).","done":"10 manual queries return sensible chunks.","checkpoint":false,"enhancement":"Version document chunks and support incremental re-indexing when a source document changes."},{"day":66,"title":"Basic RAG","phase":"RAG and data for AI","learn":"none; reuse your Day 53 prompting skills.","build":"retrieve top-k chunks, send them with the question to Claude, answer with source names.","done":"it answers your 10 test questions and cites the right document for at least 7.","checkpoint":false,"enhancement":"Measure retrieval precision/recall and answer faithfulness on a small hand-labelled evaluation set."},{"day":67,"title":"Chat UI","phase":"RAG and data for AI","learn":"Streamlit docs, chat elements.","build":"a Streamlit chat app showing the answer and an expandable list of retrieved chunks.","done":"you recorded a 30-second screen capture of it working.","checkpoint":true,"enhancement":"Add citation checks: every factual answer claim should map to a retrieved source passage; show an abstention when evidence is weak."},{"day":68,"title":"Better retrieval","phase":"RAG and data for AI","learn":"BM25 (rank_bm25 library); reciprocal rank fusion; the idea of reranking.","build":"add keyword search and fuse it with vector search. Measure hit@5 (is the right document in the top 5?) before and after.","done":"a before/after table is in the repo.","checkpoint":false,"enhancement":"Add RAG regression tests for missing context, conflicting sources, stale documents and prompt injection inside retrieved text."},{"day":69,"title":"Grounding and refusal","phase":"RAG and data for AI","learn":"Claude docs on reducing hallucinations.","build":"instruct the model to answer only from the context, cite sources, and say 'not found' otherwise. Test 10 questions the corpus cannot answer.","done":"at least 8 of 10 unanswerable questions are refused correctly.","checkpoint":false,"enhancement":"Record retrieval and generation traces, latency and token cost for each question."},{"day":70,"title":"RAG evaluation","phase":"RAG and data for AI","learn":"none; apply Day 57.","build":"grow the test set to 30 questions. Report hit@5 and MRR for retrieval, and check faithfulness of answers on 15 using an LLM judge you verify by hand.","done":"eval/report.md shows metrics for 2 configurations.","checkpoint":false,"enhancement":"Add a simple permission test matrix for at least two user roles and three document groups."},{"day":71,"title":"Data pipeline for RAG (your data engineering edge)","phase":"RAG and data for AI","learn":"none.","build":"an ingestion job that detects new, changed and deleted files by content hash, then upserts or removes the matching chunks and logs the counts. Schedule it with cron or a Databricks job.","done":"deleting a file removes its chunks from search results.","checkpoint":false},{"day":72,"title":"Text-to-SQL","phase":"RAG and data for AI","learn":"Claude docs on tool use.","build":"a DuckDB sample database. Give the model the schema and 3 sample rows; let it write SQL; run it on a read-only connection; allow only SELECT and force a LIMIT.","done":"15 questions tested, accuracy measured, 3 failures explained.","checkpoint":false},{"day":73,"title":"Governance for AI data","phase":"RAG and data for AI","learn":"basics of PII detection (regex patterns for emails and phone numbers).","build":"mask PII before embedding; add a role field to chunk metadata and filter retrieval by role; write every query and the sources used to an audit log.","done":"a restricted document never appears for the wrong role.","checkpoint":false},{"day":74,"title":"RAG service","phase":"RAG and data for AI","learn":"FastAPI 'First steps' tutorial.","build":"an /ask endpoint, a Dockerfile, a README and the eval report.","done":"docker run starts the service and a curl call returns a cited answer.","checkpoint":true,"enhancement":"Release checklist: reproducible deployment, API validation, pytest suite, RAG evaluation report, secret handling and known limitations."},{"day":75,"title":"Tool use","phase":"Agents, sub-agents, MCP and skills","learn":"the tool-use section of Anthropic Academy 'Building with the Claude API'; Claude docs on tool use.","build":"define 2 tools (weather lookup via Open-Meteo, and a calculator). Let the model request a tool, run it, and return a tool_result.","done":"'Is it hotter in Delhi or Mumbai today, and by how many degrees?' is answered using real tool calls.","checkpoint":false,"enhancement":"Re-entry refresh: rebuild the API and data pipeline locally from README instructions without relying on hidden notebook state."},{"day":76,"title":"The agent loop","phase":"Agents, sub-agents, MCP and skills","learn":"re-read your Day 75 code and note where the loop would go.","build":"from scratch, loop: call the model, if it asks for a tool run it and append the result, repeat until it finishes. Cap at 10 steps and log every step.","done":"the agent solves a 3-step question and the log shows each step.","checkpoint":false},{"day":77,"title":"Agent patterns","phase":"Agents, sub-agents, MCP and skills","learn":"Anthropic's article 'Building effective agents' (workflows vs agents; prompt chaining, routing, parallelization, orchestrator-workers, evaluator-optimizer).","build":"implement routing (classify the request, then dispatch) and prompt chaining (outline, draft, edit) for a short report writer.","done":"you can say which of your two builds is a workflow and which could be an agent.","checkpoint":false},{"day":78,"title":"Memory and context management","phase":"Agents, sub-agents, MCP and skills","learn":"context window limits; summarization as compression.","build":"summarize older turns once the history passes a token budget; keep a memory.md file the agent can read and append to.","done":"the agent remembers a fact from 30 turns ago through the memory file.","checkpoint":false},{"day":79,"title":"Sub-agents","phase":"Agents, sub-agents, MCP and skills","learn":"Claude Code docs on subagents; the orchestrator-worker pattern.","build":"a research agent where an orchestrator splits a question into 3 sub-questions, 3 workers answer each in a clean context, and a synthesizer merges the answers.","done":"you compared the output with a single prompt and noted the difference in quality and cost.","checkpoint":false},{"day":80,"title":"Multi-agent data-quality reviewer","phase":"Agents, sub-agents, MCP and skills","learn":"none.","build":"profiler (pandas statistics), critic (finds issues), summarizer (writes the report).","done":"it runs on 2 different datasets and finds at least one real issue in each.","checkpoint":true,"enhancement":"Add explicit human approval and an audit record for any operation that could modify data."},{"day":81,"title":"MCP concepts","phase":"Agents, sub-agents, MCP and skills","learn":"Anthropic Academy 'Introduction to Model Context Protocol' (start; finish by Day 84); the MCP documentation introduction.","build":"diagram host, client and server; list tools, resources and prompts with one example of each.","done":"you can explain MCP in 3 sentences to a non-technical person.","checkpoint":false},{"day":82,"title":"Use existing MCP servers","phase":"Agents, sub-agents, MCP and skills","learn":"MCP docs on connecting servers; Claude connectors documentation.","build":"connect GitHub, filesystem or Google Drive to Claude. Run 5 real tasks and note every permission prompt.","done":"notes say what each connector can read and what it can change.","checkpoint":false},{"day":83,"title":"Build your own MCP server","phase":"Agents, sub-agents, MCP and skills","learn":"MCP Python SDK quickstart.","build":"a server over a DuckDB file with tools list_tables, describe_table, run_readonly_query. Test with the MCP Inspector, then connect it to Claude.","done":"Claude answers a question about your data by calling your tools.","checkpoint":false},{"day":84,"title":"Claude Code","phase":"Agents, sub-agents, MCP and skills","learn":"Anthropic Academy 'Claude Code in Action'; Claude Code docs.","build":"install Claude Code, write a CLAUDE.md for mini-etl, then ask it to add tests and refactor one module. Review the full diff before committing.","done":"you committed a change and can explain every line Claude wrote.","checkpoint":false},{"day":85,"title":"Skills","phase":"Agents, sub-agents, MCP and skills","learn":"Anthropic Academy 'Introduction to Agent Skills'.","build":"write a skill pipeline-reviewer with a checklist (idempotency, schema changes, null handling, logging, tests). Run it on mini-etl.","done":"it found at least 3 real review comments.","checkpoint":false},{"day":86,"title":"Frameworks","phase":"Agents, sub-agents, MCP and skills","learn":"Claude Agent SDK overview; LangGraph quickstart.","build":"rebuild the Day 76 agent with one framework. Compare lines of code and how easy debugging was.","done":"a decision note says when you would use a framework and when plain code.","checkpoint":false},{"day":87,"title":"Guardrails and security","phase":"Agents, sub-agents, MCP and skills","learn":"OWASP LLM Top 10 (prompt injection, excessive agency); least-privilege principle.","build":"use a read-only database user, an allowlist of tools, human approval before any write, and redaction of secrets in logs. Test an injection hidden inside a retrieved document.","done":"a threat table lists 5 threats with a mitigation each.","checkpoint":false,"enhancement":"Expand threat tests to include prompt injection in retrieved documents and tool output, unsafe arguments, data exfiltration and excessive agency."},{"day":88,"title":"Observability","phase":"Agents, sub-agents, MCP and skills","learn":"what to trace: prompts, tool calls, latency, tokens, cost.","build":"log every agent step to JSONL and load it into DuckDB. Query the 5 most expensive runs and the slowest tool.","done":"one SQL query gives cost per run for the week.","checkpoint":false,"enhancement":"Trace model, prompt version, tool calls, token usage, latency, errors and cost; redact credentials and sensitive values."},{"day":89,"title":"Agent evaluation","phase":"Agents, sub-agents, MCP and skills","learn":"success rate and trajectory review.","build":"15 test tasks with expected outcomes. Run the agent on all, compute success rate, read 3 failed trajectories, and add the suite to CI.","done":"the suite runs in GitHub Actions.","checkpoint":false,"enhancement":"Evaluate complete agent trajectories, not just final answers; report task success, tool correctness, safety violations, latency and cost."},{"day":90,"title":"Data agent","phase":"Agents, sub-agents, MCP and skills","learn":"finish any remaining Anthropic Academy courses.","build":"given a table name, the agent profiles quality, proposes SQL fixes, asks for your approval, applies them to a copy, and re-checks.","done":"it fixes a table end to end and never touches the original without approval.","checkpoint":true,"enhancement":"Make the agent read-only by default; propose SQL changes, request approval, apply only to a copy and verify the result."},{"day":91,"title":"Design the capstone","phase":"Capstone, certification and career","learn":"","build":"a one-page spec: problem, users, architecture diagram, data sources, tools, success metrics, risks.","done":"capstone/SPEC.md is committed and lists 5 measurable success criteria.","checkpoint":false,"enhancement":"Add architecture decisions, data-flow boundaries, threat model, user roles and measurable acceptance criteria to the capstone spec."},{"day":92,"title":"Data layer","phase":"Capstone, certification and career","learn":"","build":"the vector index, the text-to-SQL tool and your MCP server exposing both.","done":"the pipeline runs end to end from a clean start.","checkpoint":false,"enhancement":"Add schema contracts, data-quality tests, idempotent ingestion and incremental processing to the bronze/silver/gold pipeline."},{"day":93,"title":"Retrieval and tools","phase":"Capstone, certification and career","learn":"","build":"an orchestrator that routes a question to SQL, retrieval or both, with sub-agents for analysis and for writing the answer.","done":"each tool works alone from a test script.","checkpoint":false,"enhancement":"Expose retrieval and SQL through validated, least-privilege MCP tools; test each tool independently and record failure modes."},{"day":94,"title":"Agent logic","phase":"Capstone, certification and career","learn":"","build":"a 30-case evaluation set, injection tests, read-only database access and an approval step for any action.","done":"10 sample questions get sensible, cited answers.","checkpoint":false,"enhancement":"Add bounded retries, explicit state transitions, tool timeouts and a deterministic fallback when routing confidence is low."},{"day":95,"title":"Evaluation and guardrails","phase":"Capstone, certification and career","learn":"","build":"containerize with Docker; deploy a Streamlit front end to a free host such as Streamlit Community Cloud or Hugging Face Spaces; keep keys in environment secrets.","done":"the evaluation report shows success rate and cost per question.","checkpoint":false,"enhancement":"Include adversarial, permission, regression and abstention tests; track quality, latency and cost together."},{"day":96,"title":"Deploy","phase":"Capstone, certification and career","learn":"","build":"a README with problem, architecture diagram, how to run, evaluation results and known limits. Record a 2-minute demo video.","done":"someone else opens a public link and asks a question.","checkpoint":false,"enhancement":"Deploy with secrets stored in host-managed environment settings; add health checks, structured logs and a rollback note."},{"day":97,"title":"Documentation and demo","phase":"Capstone, certification and career","learn":"","build":"update your headline (role plus focus, for example 'Data Engineer | AI & Agents'), your About section and your Featured links (repo and demo). Add certificates. Publish 3 posts: what you built, one lesson on RAG evaluation, one lesson on agent security.","done":"a stranger can run it from your README in under 15 minutes.","checkpoint":false,"enhancement":"Document setup, architecture, evaluation methodology, known limitations, data permissions and reproducible demo steps."},{"day":98,"title":"LinkedIn","phase":"Capstone, certification and career","learn":"","build":"answer 20 questions aloud and record yourself: SQL window functions, Spark shuffle, Delta MERGE, idempotent pipelines, RAG chunking, evaluation, the agent loop, MCP, prompt injection. Then explain your capstone in 5 minutes.","done":"the three posts are live with the repo link.","checkpoint":false},{"day":99,"title":"Interview practice","phase":"Capstone, certification and career","learn":"","build":"list what you can now do, what is still weak, and pick one specialization: AI data pipelines, agent platforms, or evaluation and governance. Check the Databricks certification page for a Generative AI Engineer certification and decide whether to take it.","done":"you re-recorded the 3 weakest answers.","checkpoint":false},{"day":100,"title":"Review and next 100 days","phase":"Capstone, certification and career","learn":"","build":"list what you can now do, what is still weak, and pick one specialization: AI data pipelines, agent platforms, or evaluation and governance. Check the Databricks certification page for a Generative AI Engineer certification and decide whether to take it.","done":"a written plan for Days 101–200 is in the repo.","checkpoint":false}];
const $=s=>document.querySelector(s);
const todayISO=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const addDays=(d,n)=>{let x=new Date(d+'T12:00:00');x.setDate(x.getDate()+n);return iso(x)};
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fmt=(s,opt={day:'numeric',month:'short',year:'numeric'})=>s?new Date(s+'T12:00:00').toLocaleDateString('en-IN',opt):'—';
const weekStart=s=>{let d=new Date(s+'T12:00:00');let day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return iso(d)};
const monthStart=s=>s.slice(0,7)+'-01';
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const phases=[...new Set(LESSONS.map(x=>x.phase))];
function schedule(){let dates={1:'2026-11-14'};let d=new Date('2026-11-14T12:00:00');for(let n=2;n<=74;n++){d.setDate(d.getDate()+1);if(d.getDay()===0)d.setDate(d.getDate()+1);dates[n]=iso(d)}const block2={75:'2027-03-18',76:'2027-03-19',77:'2027-03-20',78:'2027-03-22',79:'2027-03-23',80:'2027-03-24',81:'2027-03-25',82:'2027-03-26',83:'2027-03-27',84:'2027-03-30',85:'2027-03-31',86:'2027-04-02',87:'2027-04-03',88:'2027-04-06',89:'2027-04-07',90:'2027-04-09',91:'2027-04-10',92:'2027-04-12',93:'2027-04-13',94:'2027-04-14',95:'2027-04-15',96:'2027-04-16',97:'2027-04-17',98:'2027-04-23',99:'2027-04-27',100:'2027-04-29'};Object.assign(dates,block2);return dates}
const DATES=schedule();
const clampNumber=(value,min,max,fallback)=>{let n=Number(value);return Number.isFinite(n)?Math.min(max,Math.max(min,n)):fallback};
const safeHttpUrl=value=>{try{let u=new URL(String(value||''));return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}};
const fresh=()=>({started:false,profile:{name:'',dailyTarget:3.5,weeklyTarget:20,accountabilityPartner:'',why:'',commitment:''},lessons:{},days:{},weekly:{},monthly:{},projects:[],settings:{startDate:'2026-11-14'},createdAt:new Date().toISOString()});
function isPlainObject(x){return !!x&&typeof x==='object'&&!Array.isArray(x)}
function normalizeState(input){if(!isPlainObject(input))throw Error('Backup must contain a state object');let base=fresh();let v=isPlainObject(input.state)?input.state:input;if(!isPlainObject(v.days)||!isPlainObject(v.lessons))throw Error('Backup is missing valid days or lessons data');let profile=isPlainObject(v.profile)?v.profile:{};let out={...base,...v,profile:{...base.profile,...profile},settings:{...base.settings,...(isPlainObject(v.settings)?v.settings:{})},lessons:{},days:{},weekly:isPlainObject(v.weekly)?v.weekly:{},monthly:isPlainObject(v.monthly)?v.monthly:{},projects:[]};for(let [date,d] of Object.entries(v.days)){let dt=new Date(date+'T12:00:00');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(dt.getTime())||iso(dt)!==date||!isPlainObject(d))continue;let tasks=isPlainObject(d.tasks)?d.tasks:{};out.days[date]={tasks:{learn:!!tasks.learn,build:!!tasks.build,proof:!!tasks.proof,review:!!tasks.review},hours:clampNumber(d.hours,0,24,0),energy:clampNumber(d.energy,1,5,3),focus:clampNumber(d.focus,1,5,3),confidence:clampNumber(d.confidence,1,5,3),blockers:String(d.blockers||''),wins:String(d.wins||''),notes:String(d.notes||''),github:String(d.github||''),promise:String(d.promise||''),checkin:!!d.checkin,checkinTime:String(d.checkinTime||'')}}for(let [n,l] of Object.entries(v.lessons)){if(!/^([1-9]|[1-9]\d|100)$/.test(n)||!isPlainObject(l))continue;out.lessons[n]={...l,status:['done','in-progress','skipped','not-started'].includes(l.status)?l.status:'not-started',notes:String(l.notes||''),evidence:String(l.evidence||'')}}out.projects=(Array.isArray(v.projects)?v.projects:[]).filter(isPlainObject).slice(0,200).map((p,i)=>({id:String(p.id||`imported-${i}`).slice(0,100).replace(/[^a-zA-Z0-9_-]/g,'_'),title:String(p.title||'Untitled project').slice(0,200),note:String(p.note||'').slice(0,5000),url:safeHttpUrl(p.url),done:!!p.done}));out.profile.dailyTarget=clampNumber(out.profile.dailyTarget,0.5,12,3.5);out.profile.weeklyTarget=clampNumber(out.profile.weeklyTarget,1,60,20);out.profile.why=String(out.profile.why||'');out.profile.commitment=String(out.profile.commitment||'');out.profile.accountabilityPartner=String(out.profile.accountabilityPartner||'');return out}
let state,loadWarning='';try{let raw=localStorage.getItem('aide_state');state=raw?normalizeState(JSON.parse(raw)):fresh()}catch(err){let raw='';try{raw=localStorage.getItem('aide_state')||'';if(raw)localStorage.setItem('aide_state_corrupt_backup',raw)}catch(_){}state=fresh();loadWarning='Saved data could not be read. A safety copy was kept when browser storage allowed; do not reset or clear site data.';console.error(loadWarning,err)}
let view='overview',selectedDate=todayISO(),roadmapFilter='all',searchTerm='',monthCursor=monthStart(todayISO()),timerInt=null,timerSec=25*60;
function save(){try{localStorage.setItem('aide_state',JSON.stringify(state));let el=$('#lastSaved');if(el)el.textContent='Saved '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});return true}catch(err){console.error('Could not save progress',err);toast('Save failed: browser storage may be full or unavailable. Export a backup.');return false}}
function emptyDay(){return {tasks:{learn:false,build:false,proof:false,review:false},hours:0,energy:3,confidence:3,focus:3,blockers:'',wins:'',notes:'',github:'',promise:'',checkin:false,checkinTime:''}}
function dayData(date){return state.days[date]||emptyDay()}
function ensureDayData(date){return state.days[date]||(state.days[date]=emptyDay())}
function lessonForDate(date){return LESSONS.find(l=>DATES[l.day]===date)}
function lessonStatus(n){return state.lessons[n]?.status||'not-started'}
function setStatus(n,status){if(!LESSONS.some(l=>l.day===n)||!['done','in-progress','skipped','not-started'].includes(status))return false;let old=state.lessons[n]||{};state.lessons[n]={...old,status,updatedAt:new Date().toISOString()};if(status==='done'){state.lessons[n].completedAt=old.completedAt||todayISO()}else delete state.lessons[n].completedAt;if(save())return true;if(old&&Object.keys(old).length)state.lessons[n]=old;else delete state.lessons[n];return false}
function completed(){return LESSONS.filter(l=>lessonStatus(l.day)==='done').length}
function totalHours(){return Object.values(state.days).reduce((a,d)=>a+(+d.hours||0),0)}
function weekDates(start){return Array.from({length:7},(_,i)=>addDays(start,i))}
function weekStats(start){let ds=weekDates(start),hours=ds.reduce((a,d)=>a+(+(state.days[d]?.hours||0)),0),done=LESSONS.filter(l=>ds.includes(DATES[l.day])&&lessonStatus(l.day)==='done').length,checkins=ds.filter(d=>state.days[d]?.checkin).length;return{hours,done,checkins,ds}}
function pct(n,d){return d?Math.round(n/d*100):0}
function statusLabel(s){return ({done:'Completed','in-progress':'In progress','skipped':'Skipped','not-started':'Not started'})[s]||'Not started'}
function nav(v){view=v;document.querySelector('.sidebar')?.classList.remove('open');document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#pageTitle').textContent=({overview:'Command centre',daily:'Daily execution',roadmap:'100-lesson roadmap',weekly:'Weekly review',monthly:'Monthly retrospective',analytics:'Analytics & trends',accountability:'Accountability',projects:'Projects & evidence',settings:'Settings & backup'})[v];$('#content').innerHTML=render();window.scrollTo(0,0);if(innerWidth<700)$('#sidebar')?.classList.remove('open')}
function kpi(label,value,foot,cls=''){return `<div class="card"><div class="kpi-label">${label}</div><div class="kpi-value ${cls}">${value}</div><div class="kpi-foot">${foot}</div></div>`}
function progressBar(p,cls=''){return `<div class="progress ${cls}"><i style="width:${Math.min(100,p)}%"></i></div>`}
function chartLine(values,labels){let w=600,h=190,left=30,right=12,top=12,bottom=28,max=Math.max(1,...values),pts=values.map((v,i)=>[left+i*(w-left-right)/Math.max(1,values.length-1),top+(h-top-bottom)*(1-v/max)]),path=pts.map((p,i)=>(i?'L':'M')+p[0]+','+p[1]).join(' '),area=path+` L${pts.at(-1)[0]},${h-bottom} L${pts[0][0]},${h-bottom} Z`;return `<svg class="chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#59d5d0" stop-opacity=".25"/><stop offset="1" stop-color="#59d5d0" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(t=>`<line class="gridline" x1="${left}" x2="${w-right}" y1="${top+(h-top-bottom)*t}" y2="${top+(h-top-bottom)*t}"/>`).join('')}<path class="area" d="${area}"/><path class="line" d="${path}"/>${pts.map((p,i)=>i%Math.ceil(values.length/6)===0?`<text x="${p[0]}" y="${h-7}" text-anchor="middle">${labels[i]||''}</text>`:'').join('')}</svg>`}
function phaseProgress(){return phases.map((p,i)=>{let ls=LESSONS.filter(l=>l.phase===p),n=ls.filter(l=>lessonStatus(l.day)==='done').length;return `<div class="bar-row"><span title="${esc(p)}">Phase ${i+1}</span>${progressBar(pct(n,ls.length))}<b>${n}/${ls.length}</b></div>`}).join('')}
function recentLessons(){let ls=LESSONS.filter(l=>lessonStatus(l.day)!=='done').slice(0,4);return ls.map(l=>`<div class="lesson-row" data-open-lesson="${l.day}" role="button" tabindex="0"><div class="day-num">${l.day}</div><div class="lesson-main"><b>${esc(l.title)}</b><small>${esc(l.phase)}</small></div><span class="status">${statusLabel(lessonStatus(l.day))}</span></div>`).join('')}
function heatmap(){let end=new Date(todayISO()+'T12:00:00'),start=new Date(end);start.setDate(end.getDate()-83);let cells=[];for(let i=0;i<84;i++){let d=new Date(start);d.setDate(start.getDate()+i);let s=iso(d),h=+(state.days[s]?.hours||0),val=h===0?0:h<1?1:h<2?2:h<3.5?3:4;cells.push(`<div class="heat" data-v="${val}" title="${fmt(s)} · ${h} hrs"></div>`)}return cells.join('')}
function renderOverview(){let done=completed(),hrs=totalHours(),streak=calcStreak(),next=LESSONS.find(l=>lessonStatus(l.day)!=='done'),today=dayData(todayISO()),wk=weekStats(weekStart(todayISO())),target=+state.profile.weeklyTarget||20;let days=Array.from({length:14},(_,i)=>addDays(addDays(todayISO(),-13),i)),vals=days.map(d=>+(state.days[d]?.hours||0));return `<section class="hero"><div><div class="eyebrow">YOUR 100-LESSON TRANSFORMATION</div><h2>Make every study session count.</h2><p>One operating system for learning, building, reviewing and proving your skills. Consistency beats intensity—show up, ship evidence, reflect and improve.</p><div class="btn-row" style="margin-top:17px"><button class="btn primary" data-nav="daily">Start today's session →</button><button class="btn ghost" data-nav="accountability">Check my commitment</button></div></div><div class="hero-right"><div class="big">${pct(done,100)}%</div><div class="muted small">ROADMAP COMPLETE</div>${progressBar(done,'')}</div></section>
<div class="grid kpis">${kpi('Lessons completed',`${done}<span class="muted" style="font-size:14px"> / 100</span>`,`${100-done} lessons remaining`,'accent')}${kpi('Study hours',hrs.toFixed(1),`Target ${state.profile.dailyTarget} hrs per study day`)}${kpi('Current streak',`${streak} days`,'Consecutive check-ins or completed daily reviews','green')}${kpi('This week',`${wk.hours.toFixed(1)} hrs`,`${wk.done} lessons · ${wk.checkins}/7 check-ins`)}</div>
<div class="grid two-col"><div class="card"><div class="card-head"><h3>Study consistency</h3><span class="pill">Last 14 days · hours</span></div>${chartLine(vals,days.map(d=>new Date(d+'T12:00:00').toLocaleDateString('en',{day:'numeric',month:'short'})))}<div class="legend"><span><i></i>Daily study hours</span></div></div><div class="card"><div class="card-head"><h3>Phase completion</h3><span class="pill">${done}/100 lessons</span></div>${phaseProgress()}</div></div>
<div class="grid two-col" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Next lessons</h3><button class="btn ghost" data-nav="roadmap">View roadmap</button></div>${recentLessons()}</div><div class="card"><div class="card-head"><h3>84-day activity map</h3><span class="pill">Daily effort</span></div><div class="heatmap">${heatmap()}</div><div class="muted small" style="margin-top:12px">Less <span style="color:#51bda4">▰▰▰▰</span> More · based on hours logged</div><div class="callout" style="margin-top:15px">Accountability rule: a lesson is not complete because you watched a video. Complete the build, verify the "Done when" condition and save proof.</div></div></div>`}
function calcStreak(){let d=todayISO();if(!(state.days[d]?.checkin||state.days[d]?.tasks?.review))d=addDays(d,-1);let n=0;for(let i=0;i<400;i++){let x=addDays(d,-i);if(state.days[x]?.checkin||state.days[x]?.tasks?.review)n++;else break}return n}
function renderDaily(){let d=dayData(selectedDate),l=lessonForDate(selectedDate),isToday=selectedDate===todayISO(),next=LESSONS.find(x=>DATES[x.day]>=selectedDate&&lessonStatus(x.day)!=='done');return `<div class="split"><div><div class="eyebrow">EXECUTION LOG · ${fmt(selectedDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase()}</div><h2 style="font:600 21px 'Space Grotesk';margin:0 0 6px">${l?`Day ${l.day}: ${esc(l.title)}`:'Personal study / catch-up day'}</h2><div class="muted small">${l?esc(l.phase):'Use this day to recover, revise or work on your portfolio.'}</div></div><div class="btn-row"><button class="btn ghost" id="prevDay">←</button><input type="date" class="search" style="width:auto" id="dailyDate" value="${selectedDate}"><button class="btn ghost" id="nextDay">→</button></div></div>
<div class="grid two-col" style="margin-top:18px"><div class="card"><div class="card-head"><h3>Today's execution checklist</h3><span class="status ${Object.values(d.tasks).every(Boolean)?'done':''}">${Object.values(d.tasks).filter(Boolean).length}/4 complete</span></div><div class="task-list">${[['learn','Learn · complete the named resource'],['build','Build · write the code / finish the exercise'],['proof','Evidence · commit to GitHub or save an artifact'],['review','Review · notes, Anki cards and tomorrow plan']].map(([k,t])=>`<label class="task ${d.tasks[k]?'done':''}"><input type="checkbox" data-task="${k}" ${d.tasks[k]?'checked':''}><span>${t}</span></label>`).join('')}</div><div class="field"><label>Study time today (hours)</label><input id="hoursInput" type="number" min="0" max="24" step=".25" value="${d.hours||0}"></div><div class="field"><label>GitHub commit / evidence link</label><input id="githubInput" placeholder="https://github.com/..." value="${esc(d.github)}"></div><div class="field"><label>Today's promise (what will you ship?)</label><input id="promiseInput" placeholder="By the end of today I will..." value="${esc(d.promise)}"></div></div>
<div class="card"><div class="card-head"><h3>Learning brief</h3>${l?`<span class="pill">Lesson ${l.day}/100</span>`:'<span class="pill">Flexible day</span>'}</div>${l?`<div class="lesson-detail"><h4>LEARN</h4><p>${esc(l.learn||'No separate learning resource specified in the roadmap. Focus on building.')}</p><h4>BUILD</h4><p>${esc(l.build)}</p><h4>DONE WHEN</h4><p>${esc(l.done||'Review the lesson outcome and document what you completed.')}</p></div><div class="btn-row" style="margin-top:17px"><button class="btn primary" data-open-lesson="${l.day}">Open lesson workspace</button><button class="btn ghost" data-status="${l.day}" data-value="in-progress">Mark in progress</button>${lessonStatus(l.day)==='done'?'<span class="status done">Completed</span>':`<button class="btn" data-status="${l.day}" data-value="done">Complete lesson ✓</button>`}</div>`:`<div class="callout">No lesson is scheduled for this date in the source roadmap. Sundays are catch-up / review days. Keep this day light and close any open loops.</div>`}
<div class="field"><label>Energy level · ${d.energy}/5</label><input type="range" min="1" max="5" id="energyInput" value="${d.energy}"></div><div class="field"><label>Focus quality · ${d.focus}/5</label><input type="range" min="1" max="5" id="focusInput" value="${d.focus}"></div></div></div>
<div class="grid two-col" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Daily reflection</h3><span class="pill">2-minute journal</span></div><div class="field"><label>What did I actually accomplish?</label><textarea id="winsInput" placeholder="Be specific. What works now that didn't work before?">${esc(d.wins)}</textarea></div><div class="field"><label>What confused me / blocked me?</label><textarea id="blockersInput" placeholder="Name the obstacle, not just 'I was stuck'.">${esc(d.blockers)}</textarea></div><div class="field"><label>What is the one fix for tomorrow?</label><textarea id="notesInput" placeholder="A concrete next action...">${esc(d.notes)}</textarea></div><button class="btn primary" id="saveDaily">Save daily log</button></div><div class="card"><div class="card-head"><h3>Accountability check-in</h3><span class="status ${d.checkin?'done':''}">${d.checkin?'Checked in':'Not checked in'}</span></div><p class="muted small">A check-in means you report honestly—even if the day went badly. No fake streaks.</p><div class="field"><label>Confidence you can deliver tomorrow · ${d.confidence}/5</label><input type="range" min="1" max="5" id="confidenceInput" value="${d.confidence}"></div><label class="checkline"><input type="checkbox" id="checkinInput" ${d.checkin?'checked':''}> I have completed an honest end-of-day check-in.</label><div class="callout">If you miss a day: don't double the workload. Move unfinished work to the next catch-up window, drop stretch tasks and protect the checkpoint build.</div></div></div>`}
function renderRoadmap(){let filtered=LESSONS.filter(l=>(roadmapFilter==='all'||lessonStatus(l.day)===roadmapFilter)&&(!searchTerm||(`${l.title} ${l.phase} ${l.learn} ${l.build}`).toLowerCase().includes(searchTerm.toLowerCase())));return `<div class="split"><div><div class="eyebrow">THE MASTER PLAN</div><h2 style="font:600 21px 'Space Grotesk';margin:0">100 lessons. Seven phases. One portfolio.</h2><p class="muted small">Every lesson retains its original Learn, Build and Done-when criteria from your roadmap.</p></div><div class="pill">${completed()} / 100 complete</div></div><div class="card" style="margin:17px 0"><div class="split"><div><b>Overall completion</b><div class="muted small">${pct(completed(),100)}% · ${100-completed()} remaining</div></div><div class="kpi-value accent">${completed()}%</div></div>${progressBar(completed())}</div><div class="split" style="margin-bottom:12px;flex-wrap:wrap"><div class="tabs">${[['all','All'],['not-started','Not started'],['in-progress','In progress'],['done','Completed'],['skipped','Skipped']].map(([v,t])=>`<button class="tab ${roadmapFilter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><input class="search" id="lessonSearch" style="max-width:240px" placeholder="Search lessons..." value="${esc(searchTerm)}"></div>${phases.map((p,i)=>{let ls=filtered.filter(l=>l.phase===p);if(!ls.length)return'';let all=LESSONS.filter(l=>l.phase===p),n=all.filter(l=>lessonStatus(l.day)==='done').length;return `<div class="card" style="margin:12px 0"><div class="card-head"><div><div class="eyebrow">PHASE ${i+1}</div><h3>${esc(p)}</h3></div><span class="pill">${n}/${all.length} done</span></div>${progressBar(pct(n,all.length))}${ls.map(l=>`<div class="lesson-row" data-open-lesson="${l.day}" role="button" tabindex="0" aria-label="Open lesson ${l.day}: ${esc(l.title)}"><div class="day-num">${l.day}</div><div class="lesson-main"><b>${esc(l.title)} ${l.checkpoint?'· CHECKPOINT':''}</b><small>${fmt(DATES[l.day])} · ${esc(l.done||'Review and document the outcome')}</small></div><span class="status ${lessonStatus(l.day)==='done'?'done':lessonStatus(l.day)==='in-progress'?'inprogress':''}">${statusLabel(lessonStatus(l.day))}</span></div>`).join('')}</div>`}).join('')}`}
function renderWeekly(){let start=weekStart(selectedDate),s=weekStats(start),key=start,r=state.weekly[key]||{};let goal=+state.profile.weeklyTarget||20;let lessons=LESSONS.filter(l=>s.ds.includes(DATES[l.day]));return `<div class="split"><div><div class="eyebrow">WEEKLY OPERATING REVIEW</div><h2 style="font:600 21px 'Space Grotesk';margin:0">Review the system, not just the score.</h2><p class="muted small">${fmt(start)} – ${fmt(addDays(start,6))}</p></div><input type="date" class="search" style="width:auto" id="weeklyDate" value="${selectedDate}"></div><div class="grid kpis">${kpi('Study hours',s.hours.toFixed(1),`Target ${goal} hrs`,s.hours>=goal?'green':'')}${kpi('Lessons completed',s.done,`${lessons.length} scheduled`)}${kpi('Check-ins',`${s.checkins}/7`,'Honest daily check-ins')}${kpi('Goal attainment',`${pct(s.hours,goal)}%`,`Weekly hour target`)}</div><div class="grid two-col"><div class="card"><h3>Weekly retrospective</h3><div class="field"><label>1. Biggest win (evidence, not feelings)</label><textarea id="wWin">${esc(r.win)}</textarea></div><div class="field"><label>2. What did I plan vs actually finish?</label><textarea id="wPlan">${esc(r.plan)}</textarea></div><div class="field"><label>3. What caused friction or wasted time?</label><textarea id="wFriction">${esc(r.friction)}</textarea></div><div class="field"><label>4. What will I change next week?</label><textarea id="wChange">${esc(r.change)}</textarea></div><div class="field"><label>5. One non-negotiable deliverable next week</label><input id="wCommit" value="${esc(r.commit)}" placeholder="A testable outcome..."></div><button class="btn primary" id="saveWeekly">Save weekly review</button></div><div class="card"><div class="card-head"><h3>Execution by day</h3><span class="pill">${s.hours.toFixed(1)} hrs logged</span></div>${s.ds.map(d=>`<div class="lesson-row"><div class="day-num">${new Date(d+'T12:00:00').toLocaleDateString('en',{weekday:'short'})}</div><div class="lesson-main"><b>${fmt(d,{day:'numeric',month:'short'})} ${lessonForDate(d)?'· '+esc(lessonForDate(d).title):'· Catch-up / flex day'}</b><small>${+(state.days[d]?.hours||0)} hours · ${state.days[d]?.checkin?'check-in done':'no check-in'}</small></div><span class="status ${state.days[d]?.checkin?'done':''}">${state.days[d]?.checkin?'Logged':'Open'}</span></div>`).join('')}<div class="callout" style="margin-top:13px">A strong week is not only hours. Look for shipped evidence, understanding you can explain without notes, and a realistic plan for the next week.</div></div></div>`}
function monthDayDenominator(m){let y=+m.slice(0,4),mo=+m.slice(5,7),days=new Date(y,mo,0).getDate(),now=todayISO().slice(0,7);return m===now?Math.max(1,+todayISO().slice(8,10)):m>now?0:days}
function renderMonthly(){let m=monthCursor.slice(0,7),records=Object.entries(state.days).filter(([d,x])=>d.startsWith(m)&&(x.hours>0||x.checkin||Object.values(x.tasks||{}).some(Boolean)||x.wins||x.notes||x.blockers||x.promise||x.github)),hours=records.reduce((a,[d,x])=>a+(+x.hours||0),0),checks=records.filter(([d,x])=>x.checkin).length,done=LESSONS.filter(l=>DATES[l.day].startsWith(m)&&lessonStatus(l.day)==='done').length,r=state.monthly[m]||{};return `<div class="split"><div><div class="eyebrow">MONTHLY RETROSPECTIVE</div><h2 style="font:600 21px 'Space Grotesk';margin:0">Zoom out. Learn from the pattern.</h2><p class="muted small">Monthly review for ${new Date(m+'-15T12:00:00').toLocaleDateString('en',{month:'long',year:'numeric'})}</p></div><div class="btn-row"><button class="btn ghost" id="prevMonth">←</button><button class="btn ghost" id="nextMonth">→</button></div></div><div class="grid kpis">${kpi('Hours invested',hours.toFixed(1),'Logged study time')}${kpi('Lessons completed',done,'Scheduled in this month')}${kpi('Check-ins',checks,'Days with honest report')}${kpi('Consistency',`${pct(checks,monthDayDenominator(m))}%`,'Check-ins / calendar days')}</div><div class="grid two-col"><div class="card"><h3>Monthly reflection</h3><div class="field"><label>What capability can I now demonstrate?</label><textarea id="mCapability">${esc(r.capability)}</textarea></div><div class="field"><label>Best artifact / portfolio proof created</label><textarea id="mArtifact">${esc(r.artifact)}</textarea></div><div class="field"><label>Where did I overestimate / underestimate myself?</label><textarea id="mReality">${esc(r.reality)}</textarea></div><div class="field"><label>What should I stop, start and continue?</label><textarea id="mSsc">${esc(r.ssc)}</textarea></div><div class="field"><label>Next month's outcome (measurable)</label><textarea id="mOutcome">${esc(r.outcome)}</textarea></div><button class="btn primary" id="saveMonthly">Save monthly retrospective</button></div><div class="card"><h3>Monthly evidence & momentum</h3><div class="metric-row" style="margin:18px 0"><div>Days recorded<b>${records.length}</b></div><div>Avg hrs / logged day<b>${records.length?(hours/records.length).toFixed(1):'0.0'}</b></div><div>Check-ins<b>${checks}</b></div></div><div class="callout">Monthly review should change next month's plan. If you missed your target, reduce scope or fix the cause—don't simply demand more willpower.</div><h3 style="margin-top:22px">Lesson outcomes</h3>${LESSONS.filter(l=>DATES[l.day].startsWith(m)).map(l=>`<div class="lesson-row"><div class="day-num">${l.day}</div><div class="lesson-main"><b>${esc(l.title)}</b><small>${fmt(DATES[l.day])}</small></div><span class="status ${lessonStatus(l.day)==='done'?'done':''}">${statusLabel(lessonStatus(l.day))}</span></div>`).join('')||'<div class="empty">No lessons scheduled this month.</div>'}</div></div>`}
function renderAnalytics(){let weeks=[];for(let i=7;i>=0;i--){let st=weekStart(addDays(todayISO(),-i*7)),s=weekStats(st);weeks.push({st,h:s.hours,d:s.done,c:s.checkins})}let months={};Object.entries(state.days).forEach(([d,x])=>{let m=d.slice(0,7);months[m]=(months[m]||0)+(+x.hours||0)});let vals=weeks.map(x=>x.h),labels=weeks.map(x=>fmt(x.st,{day:'numeric',month:'short'}));let avg=weeks.reduce((a,x)=>a+x.h,0)/weeks.length;return `<div class="eyebrow">MEASURE WHAT MATTERS</div><h2 style="font:600 21px 'Space Grotesk';margin:0 0 16px">Analytics & learning signals</h2><div class="grid kpis">${kpi('Lifetime hours',totalHours().toFixed(1),'Across all logged days')}${kpi('Weekly average',avg.toFixed(1),'Last 8 weeks')}${kpi('Completed lessons',completed(),'Out of 100')}${kpi('Current streak',calcStreak(),'Consecutive check-ins or reviews','green')}</div><div class="grid two-col"><div class="card"><div class="card-head"><h3>Weekly study hours</h3><span class="pill">Last 8 weeks</span></div>${chartLine(vals,labels)}</div><div class="card"><div class="card-head"><h3>Phase completion</h3><span class="pill">Lesson count</span></div>${phaseProgress()}</div></div><div class="grid two-col" style="margin-top:16px"><div class="card"><h3>Monthly hours</h3>${Object.keys(months).sort().slice(-8).map(m=>`<div class="bar-row"><span>${new Date(m+'-15T12:00:00').toLocaleDateString('en',{month:'short',year:'2-digit'})}</span>${progressBar(pct(months[m],Math.max(20,...Object.values(months))))}<b>${months[m].toFixed(1)}</b></div>`).join('')||'<div class="empty">Log study time to see trends.</div>'}</div><div class="card"><h3>Quality signals</h3>${[['Average energy',average('energy')],['Average focus',average('focus')],['Average confidence',average('confidence')]].map(([k,v])=>`<div class="split" style="padding:13px 0;border-bottom:1px solid var(--line)"><span class="muted small">${k}</span><b>${v}/5</b></div>`).join('')}<p class="muted small">Use these signals to spot burnout or unrealistic planning—not to judge yourself.</p></div></div>`}
function average(k){let a=Object.values(state.days).filter(d=>d.checkin||d.hours>0).map(d=>+d[k]).filter(Number.isFinite);return a.length?(a.reduce((x,y)=>x+y,0)/a.length).toFixed(1):'—'}
function renderAccountability(){let p=state.profile;return `<div class="eyebrow">THE PROMISE YOU MAKE TO YOURSELF</div><h2 style="font:600 21px 'Space Grotesk';margin:0 0 8px">Accountability is a system, not a mood.</h2><p class="muted small">Make commitments small, observable and reviewable. Log reality honestly; don't game the streak.</p><div class="grid two-col" style="margin-top:17px"><div class="card"><h3>Your learning contract</h3><div class="field"><label>Why does completing this roadmap matter?</label><textarea id="profileWhy">${esc(p.why)}</textarea></div><div class="field"><label>My minimum daily commitment</label><input id="profileCommit" value="${esc(p.commitment)}" placeholder="Example: 45 minutes + one saved artifact"></div><div class="field"><label>Accountability partner (optional)</label><input id="profilePartner" value="${esc(p.accountabilityPartner)}" placeholder="Name / contact method"></div><div class="field"><label>Daily target (hours)</label><input type="number" min=".5" max="12" step=".5" id="profileDaily" value="${p.dailyTarget}"></div><div class="field"><label>Weekly target (hours)</label><input type="number" min="1" max="60" step="1" id="profileWeekly" value="${p.weeklyTarget}"></div><button class="btn primary" id="saveProfile">Save learning contract</button></div><div class="card"><h3>Accountability scoreboard</h3><div class="metric-row" style="margin:18px 0"><div>Check-ins logged<b>${Object.values(state.days).filter(d=>d.checkin).length}</b></div><div>Current streak<b>${calcStreak()}</b></div><div>Lessons shipped<b>${completed()}</b></div></div><div class="callout">Rules that keep this honest:<br>• Log time on the day it happened.<br>• A check-in is not the same as a completed lesson.<br>• A lesson is done only when the outcome is demonstrated.<br>• Don't backfill a perfect streak; record missed days accurately.<br>• Every week, name one adjustment—not ten resolutions.</div><h3 style="margin-top:20px">Recent check-ins</h3>${Object.entries(state.days).filter(([d,x])=>x.checkin).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,8).map(([d,x])=>`<div class="lesson-row"><div class="day-num">✓</div><div class="lesson-main"><b>${fmt(d)}</b><small>${x.hours||0} hours · energy ${x.energy}/5 · focus ${x.focus}/5</small></div><span class="status done">Checked in</span></div>`).join('')||`<div class="empty">No check-ins yet. Start with today's honest report.</div>`}</div></div>`}
function renderProjects(){return `<div class="split"><div><div class="eyebrow">PORTFOLIO EVIDENCE</div><h2 style="font:600 21px 'Space Grotesk';margin:0">Turn learning into proof.</h2><p class="muted small">Track artifacts that a hiring manager or technical interviewer can inspect.</p></div><button class="btn primary" id="addProject">＋ Add evidence</button></div><div class="grid three-col" style="margin:17px 0">${[['mini-etl','Mini ETL','Day 28 · Python, Pandas, Pydantic, DuckDB'],['lakehouse','End-to-end lakehouse','Day 42 · Spark, Delta, orchestration'],['rag','RAG service','Day 74 · Retrieval, evaluation, FastAPI'],['data-agent','Data quality agent','Day 90 · Agent, approval, MCP'],['capstone','Production AI data platform','Days 91–100 · Lakehouse + governed RAG + text-to-SQL + MCP + evaluation'],['ai-analysis-api','AI data analysis API','FastAPI + Pydantic + Pandas + structured LLM output'],['ml-pipeline','ML prediction pipeline','scikit-learn + PyTorch foundations + model evaluation'],['enterprise-rag','Governed enterprise RAG','Hybrid retrieval + reranking + access control + RAG evaluation']].map(([id,t,d])=>{let x=state.projects.find(p=>p.id===id)||{};return `<div class="card"><div class="card-head"><h3>${t}</h3><span class="status ${x.done?'done':''}">${x.done?'Shipped':'Planned'}</span></div><p class="muted small">${d}</p><div class="field"><label>Repository / demo URL</label><input data-project-url="${id}" value="${esc(x.url)}" placeholder="https://..."></div><div class="field"><label>Evidence / measurable result</label><textarea data-project-note="${id}" placeholder="What can someone verify?">${esc(x.note)}</textarea></div><label class="checkline"><input type="checkbox" data-project-done="${id}" ${x.done?'checked':''}> Mark artifact shipped</label><button class="btn ghost" data-save-project="${id}">Save evidence</button>${safeHttpUrl(x.url)?` <a class="status done" href="${esc(safeHttpUrl(x.url))}" target="_blank" rel="noopener noreferrer">Open ↗</a>`:""}</div>`}).join('')}</div><div class="card"><h3>Additional portfolio items</h3>${state.projects.filter(p=>!['mini-etl','lakehouse','rag','data-agent','capstone'].includes(p.id)).map(p=>`<div class="card" style="margin:12px 0"><div class="card-head"><h3>${esc(p.title)}</h3><span class="status ${p.done?'done':''}">${p.done?'Shipped':'In progress'}</span></div><div class="field"><label>Repository / certificate URL</label><input data-project-url="${esc(p.id)}" value="${esc(p.url)}" placeholder="https://..."></div><div class="field"><label>Evidence / notes</label><textarea data-project-note="${esc(p.id)}">${esc(p.note)}</textarea></div><label class="checkline"><input type="checkbox" data-project-done="${esc(p.id)}" ${p.done?'checked':''}> Mark shipped</label><button class="btn ghost" data-save-project="${esc(p.id)}">Save evidence</button>${safeHttpUrl(p.url)?` <a class="status done" href="${esc(safeHttpUrl(p.url))}" target="_blank" rel="noopener noreferrer">Open ↗</a>`:''}</div>`).join('')||'<div class="empty">Add other projects or certificates when ready.</div>'}</div>`}
function renderSettings(){return `<div class="eyebrow">YOUR DATA, YOUR CONTROL</div><h2 style="font:600 21px 'Space Grotesk';margin:0 0 16px">Settings & backup</h2><div class="grid two-col"><div class="card"><h3>Backup and restore</h3><p class="muted small">All progress is stored locally in this browser. Export a backup regularly, especially before changing devices or clearing browser data.</p><div class="btn-row" style="margin:16px 0"><button class="btn primary" id="exportData">Export full backup (.json)</button><label class="btn ghost" for="importFile">Import backup</label><input type="file" id="importFile" accept="application/json" hidden></div><div class="callout">Privacy: this version does not send your learning journal, hours or personal notes to a server. Browser storage can be cleared by device settings, so keep a backup.</div></div><div class="card"><h3>Plan configuration</h3><div class="callout">Roadmap dates are fixed to the source plan: Block 1 starts 14 Nov 2026; Block 2 activity starts 12 Mar 2027 with re-entry days; Day 75 starts 18 Mar. The break is 9 Feb–11 Mar 2027. Change dates in the roadmap itself before changing this schedule.</div><div class="field"><label>Study target per day (hours)</label><input type="number" id="dailyTargetSet" value="${state.profile.dailyTarget}" min=".5" max="12" step=".5"></div><div class="field"><label>Weekly target (hours)</label><input type="number" id="weeklyTargetSet" value="${state.profile.weeklyTarget}" min="1" max="60"></div><button class="btn primary" id="saveSettings">Save settings</button><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><button class="btn danger" id="resetData">Reset all local progress</button></div></div><div class="card" style="margin-top:16px"><h3>How the tracker calculates progress</h3><p class="muted small" style="line-height:1.7">Lesson completion is counted only when its status is set to Completed. Study hours are manually logged. A check-in is a separate honest end-of-day action. Streaks count consecutive days with a check-in or completed daily review, ending today or yesterday. The lesson schedule follows the supplied roadmap: Block 1 begins 14 Nov 2026, skips Sundays for catch-up, pauses 9 Feb–11 Mar, and Block 2 re-entry begins 12 Mar; Day 75 is scheduled for 18 Mar 2027.</p></div>`}
function render(){return ({overview:renderOverview,daily:renderDaily,roadmap:renderRoadmap,weekly:renderWeekly,monthly:renderMonthly,analytics:renderAnalytics,accountability:renderAccountability,projects:renderProjects,settings:renderSettings})[view]()}
function toast(t){let x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function openLesson(n){let l=LESSONS.find(x=>x.day===n),s=state.lessons[n]||{};$('#lessonModalContent').innerHTML=`<div class="eyebrow">LESSON ${n} / 100 · ${esc(l.phase)}</div><h2 style="font:600 21px 'Space Grotesk';margin:0 35px 12px 0">${esc(l.title)}</h2><div class="lesson-detail"><h4>LEARN</h4><p>${esc(l.learn||'No separate resource specified.')}</p><h4>BUILD</h4><p>${esc(l.build)}</p><h4>DONE WHEN</h4><p>${esc(l.done||'Document the outcome.')}</p>${l.enhancement?`<div class="enhancement"><strong>OPTIONAL ROADMAP UPGRADE · NOT A NEW LESSON</strong><p>${esc(l.enhancement)}</p></div>`:''}</div><div class="field"><label>Personal notes / what I learned</label><textarea id="lessonNotes" placeholder="Explain it in your own words...">${esc(s.notes)}</textarea></div><div class="field"><label>Evidence URL / commit</label><input id="lessonEvidence" value="${esc(s.evidence)}" placeholder="GitHub commit, notebook, demo..."></div><div class="btn-row"><button type="button" class="btn ghost" data-modal-status="in-progress" data-n="${n}">In progress</button><button type="button" class="btn primary" data-modal-status="done" data-n="${n}">Mark completed</button><button type="button" class="btn ghost" id="saveLessonNotes" data-n="${n}">Save notes</button></div>`;$('#lessonDialog').showModal()}
function changeMonth(delta){let d=new Date(monthCursor+'T12:00:00');d.setMonth(d.getMonth()+delta);monthCursor=iso(d).slice(0,7)+'-01';$('#content').innerHTML=renderMonthly()}
document.addEventListener('click',e=>{let b=e.target.closest('button,[data-nav],[data-open-lesson]');if(!b)return;if(b.dataset.nav){nav(b.dataset.nav);return}if(b.dataset.view){nav(b.dataset.view);return}if(b.dataset.openLesson){openLesson(+b.dataset.openLesson);return}if(b.dataset.status){if(setStatus(+b.dataset.status,b.dataset.value)){toast('Lesson status updated');nav(view)}return}if(b.dataset.filter){roadmapFilter=b.dataset.filter;nav('roadmap');return}if(b.id==='prevDay'){selectedDate=addDays(selectedDate,-1);nav('daily')}if(b.id==='nextDay'){selectedDate=addDays(selectedDate,1);nav('daily')}if(b.id==='saveDaily'){saveDaily();return}if(b.id==='saveWeekly'){saveWeekly();return}if(b.id==='saveMonthly'){saveMonthly();return}if(b.id==='prevMonth')changeMonth(-1);if(b.id==='nextMonth')changeMonth(1);if(b.id==='saveProfile')saveProfile();if(b.id==='saveSettings')saveSettings();if(b.id==='exportData')exportData();if(b.id==='resetData'){if(confirm('Permanently clear all local progress? Export a backup first.')){let previous=state;state=fresh();if(save())nav('overview');else state=previous}}if(b.id==='saveLessonNotes'){let n=+b.dataset.n;state.lessons[n]={...(state.lessons[n]||{}),notes:$('#lessonNotes').value,evidence:$('#lessonEvidence').value};if(save())toast('Lesson notes saved')}if(b.dataset.modalStatus){let n=+b.dataset.n;state.lessons[n]={...(state.lessons[n]||{}),notes:$('#lessonNotes').value,evidence:$('#lessonEvidence').value};if(setStatus(n,b.dataset.modalStatus)){$('#lessonDialog').close();nav(view);toast('Lesson updated')}}if(b.id==='addProject'){let title=prompt('Project / certificate name');if(title){state.projects.push({id:'custom-'+Date.now(),title,note:'',url:'',done:false});save();nav('projects')}}if(b.dataset.saveProject){let id=b.dataset.saveProject;let old=state.projects.find(p=>p.id===id)||{id,title:id};let urlField=[...document.querySelectorAll('[data-project-url]')].find(x=>x.dataset.projectUrl===id),noteField=[...document.querySelectorAll('[data-project-note]')].find(x=>x.dataset.projectNote===id),doneField=[...document.querySelectorAll('[data-project-done]')].find(x=>x.dataset.projectDone===id);if(!urlField||!noteField||!doneField)return;old.url=safeHttpUrl(urlField.value);if(urlField.value.trim()&&!old.url){toast('Use a valid http:// or https:// URL');return}old.note=noteField.value;old.done=doneField.checked;if(!state.projects.includes(old))state.projects.push(old);if(save())toast('Evidence saved')}})
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-open-lesson]')){e.preventDefault();openLesson(+e.target.dataset.openLesson)}});
document.addEventListener('change',e=>{let t=e.target;if(t.id==='dailyDate'){selectedDate=t.value;nav('daily')}if(t.id==='weeklyDate'){selectedDate=t.value;nav('weekly')}if(t.id==='checkinInput'){ensureDayData(selectedDate).checkin=t.checked;ensureDayData(selectedDate).checkinTime=t.checked?new Date().toISOString():'';save();nav('daily')}if(t.dataset.task){let d=ensureDayData(selectedDate);d.tasks[t.dataset.task]=t.checked;let row=t.closest('.task');if(row)row.classList.toggle('done',t.checked);let badge=document.querySelector('.task-list')?.parentElement?.querySelector('.status');if(badge){let count=Object.values(d.tasks).filter(Boolean).length;badge.textContent=count+'/4 complete';badge.classList.toggle('done',count===4)}save()}if(t.id==='importFile')importData(t.files[0]);if(t.dataset.projectDone){let id=t.dataset.projectDone;let p=state.projects.find(x=>x.id===id)||{id,title:id};p.done=t.checked;if(!state.projects.includes(p))state.projects.push(p);save();let card=t.closest('.card');let badge=card?.querySelector('.card-head .status');if(badge){badge.textContent=p.done?'Shipped':'Planned';badge.classList.toggle('done',p.done)}}})
document.addEventListener('input',e=>{if(e.target.id==='lessonSearch'){searchTerm=e.target.value;let pos=e.target.selectionStart;$('#content').innerHTML=renderRoadmap();let x=$('#lessonSearch');x.focus();x.setSelectionRange(pos,pos)}if(['energyInput','focusInput','confidenceInput'].includes(e.target.id)){let d=ensureDayData(selectedDate),k=e.target.id.replace('Input','');d[k]=+e.target.value;let label=e.target.previousElementSibling;if(label)label.textContent=({energy:'Energy level',focus:'Focus quality',confidence:'Confidence you can deliver tomorrow'}[k])+` · ${d[k]}/5`;save()}})
function saveDaily(){let d=ensureDayData(selectedDate);d.hours=clampNumber($('#hoursInput').value,0,24,0);d.github=$('#githubInput').value;d.promise=$('#promiseInput').value;d.wins=$('#winsInput').value;d.blockers=$('#blockersInput').value;d.notes=$('#notesInput').value;if(save())toast('Daily execution log saved')}
function saveWeekly(){let k=weekStart(selectedDate);state.weekly[k]={win:$('#wWin').value,plan:$('#wPlan').value,friction:$('#wFriction').value,change:$('#wChange').value,commit:$('#wCommit').value,savedAt:new Date().toISOString()};if(save())toast('Weekly retrospective saved')}
function saveMonthly(){let k=monthCursor.slice(0,7);state.monthly[k]={capability:$('#mCapability').value,artifact:$('#mArtifact').value,reality:$('#mReality').value,ssc:$('#mSsc').value,outcome:$('#mOutcome').value,savedAt:new Date().toISOString()};if(save())toast('Monthly retrospective saved')}
function saveProfile(){let p=state.profile;p.why=$('#profileWhy').value;p.commitment=$('#profileCommit').value;p.accountabilityPartner=$('#profilePartner').value;p.dailyTarget=clampNumber($('#profileDaily').value,0.5,12,3.5);p.weeklyTarget=clampNumber($('#profileWeekly').value,1,60,20);if(save()){toast('Learning contract saved');nav('accountability')}}
function saveSettings(){state.profile.dailyTarget=clampNumber($('#dailyTargetSet').value,0.5,12,3.5);state.profile.weeklyTarget=clampNumber($('#weeklyTargetSet').value,1,60,20);if(save()){toast('Settings saved');nav('settings')}}
function exportData(){let blob=new Blob([JSON.stringify({version:2,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ai-data-command-centre-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup exported')}
function importData(file){if(!file)return;let r=new FileReader();r.onload=()=>{try{let restored=normalizeState(JSON.parse(r.result));if(confirm('Replace current progress with this backup? Export your current data first if you may need it.')){let previous=state;state=restored;if(save()){nav('overview');toast('Backup restored')}else{state=previous}}}catch(e){alert('Could not import this backup: '+e.message)}};r.onerror=()=>alert('Could not read the selected backup file.');r.readAsText(file)}

$('#quickCheckin').onclick=()=>{selectedDate=todayISO();nav('daily');setTimeout(()=>{let x=$('#checkinInput');if(x&&!x.checked){x.checked=true;x.dispatchEvent(new Event('change',{bubbles:true}))}},0)};
$('#mobileMenu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
$('#dateChip').textContent=fmt(todayISO(),{weekday:'short',day:'numeric',month:'short'});
nav('overview');if(loadWarning)toast(loadWarning);else save();
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
